const clientIP = $json.headers['x-forwarded-for'] || $json.headers['x-real-ip'] || 'unknown';
const email = $json.body.email || '';
const username = $json.body.username || '';

if (!email && !username) {
  return { error: 'Email or username required', code: 400 };
}

if (email && !email.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)) {
  return { error: 'Invalid email format', code: 400 };
}

if (username && !username.match(/^[a-zA-Z0-9_.-]{2,40}$/)) {
  return { error: 'Invalid username format', code: 400 };
}

return {
  clientIP,
  email: email.toLowerCase().trim(),
  username: username.toLowerCase().trim(),
  timestamp: Date.now(),
  valid: true
};

const input = $('Validate Input').first().json;
const allItems = $input.all();

let breaches = [];
let hibpError = null;

if (allItems.length > 0 && allItems[0].json.Name) {
  breaches = allItems.map(item => ({
    name: item.json.Name,
    title: item.json.Title || item.json.Name,
    domain: item.json.Domain || '',
    breachDate: item.json.BreachDate || '',
    addedDate: item.json.AddedDate || '',
    pwnCount: item.json.PwnCount || 0,
    description: item.json.Description || '',
    dataClasses: item.json.DataClasses || [],
    isVerified: item.json.IsVerified || false,
    isSensitive: item.json.IsSensitive || false,
    logoPath: item.json.LogoPath ? `https://haveibeenpwned.com${item.json.LogoPath}` : null
  }));
} else if (allItems[0]?.json?.statusCode === 404) {
  breaches = [];
} else if (allItems[0]?.json?.statusCode === 429) {
  hibpError = 'Rate limited - try again later';
}

return {
  ...input,
  breaches,
  breachCount: breaches.length,
  hibpError
};

// Platform enumeration using n8n's built-in HTTP helper
const input = $json;
const username = input.username;

if (!username) {
  return { ...input, platforms: [], platformCount: 0, platformsFound: 0 };
}

// All platforms we check - expanded list
const platforms = [
  { name: 'GitHub', url: `https://github.com/${username}`, apiUrl: `https://api.github.com/users/${username}`, icon: '🙈', checkType: 'status' },
  { name: 'GitLab', url: `https://gitlab.com/${username}`, apiUrl: `https://gitlab.com/api/v4/users?username=${username}`, icon: '🦊', checkType: 'array' },
  { name: 'Reddit', url: `https://reddit.com/user/${username}`, apiUrl: `https://www.reddit.com/user/${username}/about.json`, icon: '🤖', checkType: 'status' },
  { name: 'Dev.to', url: `https://dev.to/${username}`, apiUrl: `https://dev.to/api/users/by_username?url=${username}`, icon: '👩‍💻', checkType: 'status' },
  { name: 'Hacker News', url: `https://news.ycombinator.com/user?id=${username}`, apiUrl: `https://hacker-news.firebaseio.com/v0/user/${username}.json`, icon: '📰', checkType: 'notnull' },
  { name: 'Keybase', url: `https://keybase.io/${username}`, apiUrl: `https://keybase.io/_/api/1.0/user/lookup.json?username=${username}`, icon: '🔐', checkType: 'keybase' },
  { name: 'npm', url: `https://www.npmjs.com/~${username}`, apiUrl: `https://registry.npmjs.org/-/user/org.couchdb.user:${username}`, icon: '📦', checkType: 'status' },
  { name: 'PyPI', url: `https://pypi.org/user/${username}/`, apiUrl: null, icon: '🐍', checkType: 'none' },
  { name: 'Imgur', url: `https://imgur.com/user/${username}`, apiUrl: `https://api.imgur.com/account/v1/accounts/${username}?client_id=546c25a59c58ad7`, icon: '🖼️', checkType: 'status' },
  { name: 'Pastebin', url: `https://pastebin.com/u/${username}`, apiUrl: `https://pastebin.com/u/${username}`, icon: '📋', checkType: 'status' },
  { name: 'Twitter/X', url: `https://x.com/${username}`, apiUrl: null, icon: '𝕏', checkType: 'none' },
  { name: 'Instagram', url: `https://instagram.com/${username}`, apiUrl: null, icon: '📷', checkType: 'none' },
  { name: 'TikTok', url: `https://tiktok.com/@${username}`, apiUrl: null, icon: '🎵', checkType: 'none' },
  { name: 'YouTube', url: `https://youtube.com/@${username}`, apiUrl: null, icon: '▶️', checkType: 'none' },
  { name: 'Twitch', url: `https://twitch.tv/${username}`, apiUrl: null, icon: '🎮', checkType: 'none' },
  { name: 'LinkedIn', url: `https://linkedin.com/in/${username}`, apiUrl: null, icon: '💼', checkType: 'none' },
  { name: 'Medium', url: `https://medium.com/@${username}`, apiUrl: null, icon: '📝', checkType: 'none' },
  { name: 'Pinterest', url: `https://pinterest.com/${username}`, apiUrl: null, icon: '📌', checkType: 'none' }
];

const results = [];

for (const platform of platforms) {
  let found = false;
  let checkable = !!platform.apiUrl;

  if (platform.apiUrl) {
    try {
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url: platform.apiUrl,
        headers: { 
          'User-Agent': 'SHADOWPRINT-Scanner/2.0',
          'Accept': 'application/json'
        },
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: 8000
      });

      const status = response.statusCode;
      const body = response.body;

      if (platform.checkType === 'status') {
        found = status === 200;
      } else if (platform.checkType === 'array') {
        found = Array.isArray(body) && body.length > 0;
      } else if (platform.checkType === 'notnull') {
        found = body !== null && body !== 'null' && status === 200;
      } else if (platform.checkType === 'keybase') {
        found = body?.status?.code === 0;
      }
    } catch (e) {
      found = false;
    }
  }

  results.push({
    name: platform.name,
    url: platform.url,
    icon: platform.icon,
    found: found,
    checkable: checkable
  });
}

const platformsFound = results.filter(p => p.found).length;

return {
  ...input,
  platforms: results,
  platformsFound,
  username
};

