function md5(string) {
  function rotateLeft(val, shift) {
    return (val << shift) | (val >>> (32 - shift));
  }

  function addUnsigned(x, y) {
    const x8 = x & 0x80000000;
    const y8 = y & 0x80000000;
    const x4 = x & 0x40000000;
    const y4 = y & 0x40000000;
    const result = (x & 0x3FFFFFFF) + (y & 0x3FFFFFFF);
    if (x4 & y4) return result ^ 0x80000000 ^ x8 ^ y8;
    if (x4 | y4) {
      if (result & 0x40000000) return result ^ 0xC0000000 ^ x8 ^ y8;
      return result ^ 0x40000000 ^ x8 ^ y8;
    }
    return result ^ x8 ^ y8;
  }

  function F(x, y, z) { return (x & y) | (~x & z); }
  function G(x, y, z) { return (x & z) | (y & ~z); }
  function H(x, y, z) { return x ^ y ^ z; }
  function I(x, y, z) { return y ^ (x | ~z); }

  function FF(a, b, c, d, x, s, ac) {
    a = addUnsigned(a, addUnsigned(addUnsigned(F(b, c, d), x), ac));
    return addUnsigned(rotateLeft(a, s), b);
  }
  function GG(a, b, c, d, x, s, ac) {
    a = addUnsigned(a, addUnsigned(addUnsigned(G(b, c, d), x), ac));
    return addUnsigned(rotateLeft(a, s), b);
  }
  function HH(a, b, c, d, x, s, ac) {
    a = addUnsigned(a, addUnsigned(addUnsigned(H(b, c, d), x), ac));
    return addUnsigned(rotateLeft(a, s), b);
  }
  function II(a, b, c, d, x, s, ac) {
    a = addUnsigned(a, addUnsigned(addUnsigned(I(b, c, d), x), ac));
    return addUnsigned(rotateLeft(a, s), b);
  }

  const words = [];
  let byteCount = string.length;
  for (let i = 0; i < byteCount; i++) {
    const position = i >>> 2;
    words[position] = words[position] || 0;
    words[position] |= string.charCodeAt(i) << ((i % 4) * 8);
  }
  const bitCount = byteCount * 8;
  words[byteCount >>> 2] |= 0x80 << ((byteCount % 4) * 8);
  words[(((byteCount + 8) >>> 6) << 4) + 14] = bitCount;

  let a = 0x67452301, b = 0xEFCDAB89, c = 0x98BADCFE, d = 0x10325476;

  for (let i = 0; i < words.length; i += 16) {
    const AA = a, BB = b, CC = c, DD = d;
    a = FF(a, b, c, d, words[i], 7, 0xD76AA478);
    d = FF(d, a, b, c, words[i+1], 12, 0xE8C7B756);
    c = FF(c, d, a, b, words[i+2], 17, 0x242070DB);
    b = FF(b, c, d, a, words[i+3], 22, 0xC1BDCEEE);
    a = FF(a, b, c, d, words[i+4], 7, 0xF57C0FAF);
    d = FF(d, a, b, c, words[i+5], 12, 0x4787C62A);
    c = FF(c, d, a, b, words[i+6], 17, 0xA8304613);
    b = FF(b, c, d, a, words[i+7], 22, 0xFD469501);
    a = FF(a, b, c, d, words[i+8], 7, 0x698098D8);
    d = FF(d, a, b, c, words[i+9], 12, 0x8B44F7AF);
    c = FF(c, d, a, b, words[i+10], 17, 0xFFFF5BB1);
    b = FF(b, c, d, a, words[i+11], 22, 0x895CD7BE);
    a = FF(a, b, c, d, words[i+12], 7, 0x6B901122);
    d = FF(d, a, b, c, words[i+13], 12, 0xFD987193);
    c = FF(c, d, a, b, words[i+14], 17, 0xA679438E);
    b = FF(b, c, d, a, words[i+15], 22, 0x49B40821);
    a = GG(a, b, c, d, words[i+1], 5, 0xF61E2562);
    d = GG(d, a, b, c, words[i+6], 9, 0xC040B340);
    c = GG(c, d, a, b, words[i+11], 14, 0x265E5A51);
    b = GG(b, c, d, a, words[i], 20, 0xE9B6C7AA);
    a = GG(a, b, c, d, words[i+5], 5, 0xD62F105D);
    d = GG(d, a, b, c, words[i+10], 9, 0x02441453);
    c = GG(c, d, a, b, words[i+15], 14, 0xD8A1E681);
    b = GG(b, c, d, a, words[i+4], 20, 0xE7D3FBC8);
    a = GG(a, b, c, d, words[i+9], 5, 0x21E1CDE6);
    d = GG(d, a, b, c, words[i+14], 9, 0xC33707D6);
    c = GG(c, d, a, b, words[i+3], 14, 0xF4D50D87);
    b = GG(b, c, d, a, words[i+8], 20, 0x455A14ED);
    a = GG(a, b, c, d, words[i+13], 5, 0xA9E3E905);
    d = GG(d, a, b, c, words[i+2], 9, 0xFCEFA3F8);
    c = GG(c, d, a, b, words[i+7], 14, 0x676F02D9);
    b = GG(b, c, d, a, words[i+12], 20, 0x8D2A4C8A);
    a = HH(a, b, c, d, words[i+5], 4, 0xFFFA3942);
    d = HH(d, a, b, c, words[i+8], 11, 0x8771F681);
    c = HH(c, d, a, b, words[i+11], 16, 0x6D9D6122);
    b = HH(b, c, d, a, words[i+14], 23, 0xFDE5380C);
    a = HH(a, b, c, d, words[i+1], 4, 0xA4BEEA44);
    d = HH(d, a, b, c, words[i+4], 11, 0x4BDECFA9);
    c = HH(c, d, a, b, words[i+7], 16, 0xF6BB4B60);
    b = HH(b, c, d, a, words[i+10], 23, 0xBEBFBC70);
    a = HH(a, b, c, d, words[i+13], 4, 0x289B7EC6);
    d = HH(d, a, b, c, words[i], 11, 0xEAA127FA);
    c = HH(c, d, a, b, words[i+3], 16, 0xD4EF3085);
    b = HH(b, c, d, a, words[i+6], 23, 0x04881D05);
    a = HH(a, b, c, d, words[i+9], 4, 0xD9D4D039);
    d = HH(d, a, b, c, words[i+12], 11, 0xE6DB99E5);
    c = HH(c, d, a, b, words[i+15], 16, 0x1FA27CF8);
    b = HH(b, c, d, a, words[i+2], 23, 0xC4AC5665);
    a = II(a, b, c, d, words[i], 6, 0xF4292244);
    d = II(d, a, b, c, words[i+7], 10, 0x432AFF97);
    c = II(c, d, a, b, words[i+14], 15, 0xAB9423A7);
    b = II(b, c, d, a, words[i+5], 21, 0xFC93A039);
    a = II(a, b, c, d, words[i+12], 6, 0x655B59C3);
    d = II(d, a, b, c, words[i+3], 10, 0x8F0CCC92);
    c = II(c, d, a, b, words[i+10], 15, 0xFFEFF47D);
    b = II(b, c, d, a, words[i+1], 21, 0x85845DD1);
    a = II(a, b, c, d, words[i+8], 6, 0x6FA87E4F);
    d = II(d, a, b, c, words[i+15], 10, 0xFE2CE6E0);
    c = II(c, d, a, b, words[i+6], 15, 0xA3014314);
    b = II(b, c, d, a, words[i+13], 21, 0x4E0811A1);
    a = II(a, b, c, d, words[i+4], 6, 0xF7537E82);
    d = II(d, a, b, c, words[i+11], 10, 0xBD3AF235);
    c = II(c, d, a, b, words[i+2], 15, 0x2AD7D2BB);
    b = II(b, c, d, a, words[i+9], 21, 0xEB86D391);
    a = addUnsigned(a, AA);
    b = addUnsigned(b, BB);
    c = addUnsigned(c, CC);
    d = addUnsigned(d, DD);
  }

  const hex = (n) => {
    let s = '';
    for (let i = 0; i < 4; i++) s += ('0' + ((n >> (i * 8)) & 0xFF).toString(16)).slice(-2);
    return s;
  };

  return hex(a) + hex(b) + hex(c) + hex(d);
}

const gravatarHash = email ? md5(email.toLowerCase().trim()) : '';

return {
  ...input,
  gravatarHash,
  gravatarUrl: gravatarHash ? `https://www.gravatar.com/avatar/${gravatarHash}?d=404` : null
};

const processedData = $('Gravatar Setup').first().json;
const gravatarResponse = $json;

const hasGravatar = gravatarResponse.statusCode === 200;

const breaches = processedData.breaches || [];
const breachCount = breaches.length;

const platforms = processedData.platforms || [];
const platformsFound = processedData.platformsFound || 0;

let score = 0;
score += Math.min(50, breachCount * 8);
const verifiedBreaches = breaches.filter(b => b.isVerified).length;
score += verifiedBreaches * 3;
score += platformsFound * 5;
if (hasGravatar) score += 5;
score = Math.min(99, Math.max(5, score));

let riskLevel = 'LOW';
if (score >= 30 && score < 60) riskLevel = 'MODERATE';
if (score >= 60) riskLevel = 'HIGH';

const scanId = Math.random().toString(36).substring(2, 10).toUpperCase();

const recommendations = [];

if (breachCount > 0) {
  recommendations.push({
    icon: '🔐',
    title: 'Change Compromised Passwords',
    description: `Your email was found in ${breachCount} data breach${breachCount > 1 ? 'es' : ''}. Change passwords immediately for affected services.`,
    priority: 'high'
  });
}

if (breaches.some(b => b.dataClasses && b.dataClasses.includes('Passwords'))) {
  recommendations.push({
    icon: '⚠️',
    title: 'Password Exposed',
    description: 'Your password was directly exposed in at least one breach. Change it everywhere you used it.',
    priority: 'high'
  });
}

if (platformsFound > 3) {
  recommendations.push({
    icon: '👁️',
    title: 'Review Privacy Settings',
    description: `Found ${platformsFound} public profiles. Consider making accounts private.`,
    priority: 'medium'
  });
}

recommendations.push({
  icon: '🛡️',
  title: 'Enable 2FA',
  description: 'Add two-factor authentication to all accounts. Use an authenticator app over SMS.',
  priority: score > 40 ? 'high' : 'medium'
});

if (hasGravatar) {
  recommendations.push({
    icon: '🖼️',
    title: 'Gravatar Detected',
    description: 'Your email has a public Gravatar profile image, which can be used to identify you across sites.',
    priority: 'low'
  });
}

recommendations.push({
  icon: '📧',
  title: 'Use Email Aliases',
  description: 'Use unique email aliases for different services to limit exposure.',
  priority: 'low'
});

return {
  success: true,
  scanId,
  target: processedData.email || processedData.username,
  targetType: processedData.email ? 'email' : 'username',
  score,
  riskLevel,
  breaches: breaches.map(b => ({
    name: b.title || b.name,
    domain: b.domain,
    date: b.breachDate,
    records: b.pwnCount ? b.pwnCount.toLocaleString() : 'Unknown',
    dataTypes: b.dataClasses || [],
    logo: b.logoPath,
    verified: b.isVerified
  })),
  breachCount,
  platforms: platforms.sort((a, b) => b.found - a.found),
  platformsFound,
  hasGravatar,
  gravatarUrl: hasGravatar ? `https://www.gravatar.com/avatar/${processedData.gravatarHash}` : null,
  recommendations: recommendations.slice(0, 5),
  scannedAt: new Date().toISOString()
};
